// End capacity backend wire.

it("attaches every figure from the complete public128 backend wire without recomputing values or memberships", () => {
  const answer = adaptTurn(capacityBackendWire)!;
  expect(answer.figures).toHaveLength(128);
  expect(new Set(answer.figures.map((figure) => figure.id)).size).toBe(128);
  for (const [index, figure] of answer.figures.entries()) {
    const original = capacityBackendWire.figures[index];
    expect(figure.id).toBe(original.id);
    expect(figure.numerical).toMatchObject({ value: original.value, quantity: original.quantity, kind: original.kind, grade: original.grade, currency: original.currency, dated: original.dated, boundary: original.boundary, subject: original.subject });
    expect(figure.receiptState).toBe("ready");
    expect(figure.numericalReceipts?.map((receipt) => receipt.id)).toEqual(original.receipt_ids);
    expect(figure.numericalReceipts?.every((receipt) => receipt.figureIds.includes(figure.id))).toBe(true);
  }
  for (const index of [0, 63, 127]) {
    const selected = answer.figures[index];
    const evidence = conversationEvidenceFigure(selected);
    expect(evidence.evidenceLinks).toEqual([]);
    expect(selected.numericalReceipts?.[0].figureIds).toEqual(capacityBackendWire.numerical_receipts[index % 4].figure_ids);
    expect(selected.numericalReceipts?.[0].sourceRecords).toEqual([]);
  }
});

it("keeps unavailable handling for duplicate, missing and crossed memberships at128", () => {
  const duplicateReceipt = structuredClone(capacityBackendWire);
  duplicateReceipt.numerical_receipts.push(structuredClone(duplicateReceipt.numerical_receipts[0]));
  expect(adaptTurn(duplicateReceipt)!.figures.every((figure) => figure.receiptState === "unavailable")).toBe(true);
  const duplicateMember = structuredClone(capacityBackendWire);
  duplicateMember.numerical_receipts[0].figure_ids.push(duplicateMember.numerical_receipts[0].figure_ids[0]);
  expect(adaptTurn(duplicateMember)!.figures.every((figure) => figure.receiptState === "unavailable")).toBe(true);
  const duplicateAnswer = structuredClone(capacityBackendWire);
  duplicateAnswer.figures[1].id = duplicateAnswer.figures[0].id;
  expect(adaptTurn(duplicateAnswer)!.figures.every((figure) => figure.receiptState === "unavailable")).toBe(true);
  const missing = structuredClone(capacityBackendWire);
  missing.numerical_receipts[0].figure_ids.shift();
  const missingAnswer = adaptTurn(missing)!;
  expect(missingAnswer.figures[0].receiptState).toBe("unavailable");
  expect(missingAnswer.figures[1].receiptState).toBe("ready");
  const crossed = structuredClone(capacityBackendWire);
  crossed.figures[0].receipt_ids = [crossed.numerical_receipts[1].id];
  const crossedAnswer = adaptTurn(crossed)!;
  expect(crossedAnswer.figures[0].receiptState).toBe("unavailable");
  expect(crossedAnswer.figures[1].receiptState).toBe("ready");
});
